Schema:
CREATE TABLE warehouses (id INTEGER, name TEXT); CREATE TABLE bins (id INTEGER, warehouse_id INTEGER);
Question: Show every warehouse with its bin count, including warehouses with no bins. Sort by warehouse ID.

Schema:
CREATE TABLE parcels (id INTEGER, promised_at TEXT, received_at TEXT);
Question: Count parcels received strictly later than promised. Do not count parcels not yet received.

Schema:
CREATE TABLE ledger (id INTEGER, account_code TEXT, amount REAL);
Question: Find accounts whose ledger entries sum to exactly zero. Order by account code.

Schema:
CREATE TABLE experiments (id INTEGER, name TEXT, accuracy REAL, finished_at TEXT);
Question: Show the three completed experiments with highest accuracy, breaking ties by ID ascending.

Schema:
CREATE TABLE attendees (id INTEGER, email TEXT, checked_in INTEGER);
Question: Count distinct non-null email addresses among checked-in attendees.

Schema:
CREATE TABLE licenses (id INTEGER, customer_id INTEGER, revoked_at TEXT);
Question: Show customers with more than two active licenses. Active means revoked_at is null. Sort by customer ID.

Schema:
CREATE TABLE sensor_readings (id INTEGER, recorded_at TEXT, value REAL);
Question: Average readings from 2026-09-01 inclusive to 2026-09-08 exclusive.

Schema:
CREATE TABLE invitations (id INTEGER, invited_email TEXT, accepted_at TEXT);
Question: List pending invitation emails alphabetically, without duplicates.

Schema:
CREATE TABLE baskets (id INTEGER); CREATE TABLE basket_items (basket_id INTEGER, quantity INTEGER, price REAL);
Question: Calculate the total cost of basket 11, returning zero when there are no items.

Schema:
CREATE TABLE redirects (id INTEGER, source_path TEXT, destination_path TEXT, enabled INTEGER);
Question: Show enabled redirects whose destination is missing or empty, ordered by source path.
